import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || "http://localhost:8080";

export default function PaymentNumber() {
  const [bkash, setBkash] = useState("");
  const [nagad, setNagad] = useState("");
  const [role, setRole] = useState("");

  const authToken = localStorage.getItem("authToken");
  const navigate = useNavigate();

  useEffect(() => {
    if (!authToken) return;

    // Fetch user role
    axios
      .get(`${API_BASE_URL}/api/user/profile`, {
        headers: { Authorization: `Bearer ${authToken}` },
      })
      .then((res) => {
        setRole(res.data.role || "");
      })
      .catch((err) => {
        console.error("Error fetching profile:", err);
        alert("Failed to load profile");
      });

    // Fetch payment numbers
    axios
      .get(`${API_BASE_URL}/api/payment-config`, {
        headers: { Authorization: `Bearer ${authToken}` },
      })
      .then((res) => {
        const data = res.data;
        const bkashConfig = data.find((c) => c.method === "bKash");
        const nagadConfig = data.find((c) => c.method === "Nagad");

        if (bkashConfig) setBkash(bkashConfig.number);
        if (nagadConfig) setNagad(nagadConfig.number);
      })
      .catch((err) => console.error("Error loading payment configs:", err));
  }, [authToken]);

  // Save payment number (admin only)
  const saveNumber = (method, number) => {
    if (!number) {
      alert("❌ Please enter a number");
      return;
    }

    axios
      .post(
        `${API_BASE_URL}/api/payment-config/admin/update`,
        null,
        {
          params: { method, number },
          headers: { Authorization: `Bearer ${authToken}` },
        }
      )
      .then(() => alert(`✅ ${method} number updated successfully`))
      .catch((err) => {
        console.error("Error saving payment number:", err);
        if (err.response && err.response.status === 403) {
          alert("❌ Permission denied (Admin only)");
        } else {
          alert("❌ Update failed");
        }
      });
  };

  // Render input field
  const renderField = (label, color, value, setValue, method) => (
    <div
      style={{
        border: "1px solid #ddd",
        padding: "20px",
        borderRadius: "10px",
        marginBottom: "25px",
        backgroundColor: "#ffffff",
        boxShadow: "0 2px 6px rgba(0,0,0,0.05)",
      }}
    >
      <h3 style={{ marginBottom: "12px", color, fontWeight: "bold" }}>{label}</h3>
      <input
        type="text"
        value={value}
        placeholder={`Enter ${label}`}
        onChange={(e) => setValue(e.target.value)}
        disabled={role.toUpperCase() !== "ADMIN"}
        style={{
          width: "100%",
          padding: "10px",
          border: "1px solid #ccc",
          borderRadius: "6px",
          marginBottom: "12px",
          fontSize: "16px",
        }}
      />
      {role.toUpperCase() === "ADMIN" && (
        <button
          onClick={() => saveNumber(method, value)}
          style={{
            backgroundColor: color,
            color: "white",
            padding: "10px 20px",
            border: "none",
            borderRadius: "6px",
            cursor: "pointer",
            fontSize: "16px",
          }}
        >
          Save {label}
        </button>
      )}
    </div>
  );

  return (
    <div style={{ padding: "20px", maxWidth: "600px", margin: "auto" }}>
      {/* Back Button */}
      <button
        onClick={() => navigate("/")}
        style={{
          backgroundColor: "#1976d2",
          color: "white",
          padding: "8px 16px",
          border: "none",
          borderRadius: "6px",
          cursor: "pointer",
          marginBottom: "20px",
        }}
      >
        ← Back
      </button>

      <h2 style={{ textAlign: "center", marginBottom: "30px" }}>
        💳 Payment Number Settings
      </h2>

      {renderField("bKash Number", "#d81b60", bkash, setBkash, "bKash")}
      {renderField("Nagad Number", "#ff6f00", nagad, setNagad, "Nagad")}
    </div>
  );
}
